	}

	// Parse, truncate, re-serialize
	lines, err := transcript.ParseFromBytes(session.NativeData)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	truncated := TruncateAtUUID(lines, uuid)

