306	// ClaimSessionStartBanner records that the SessionStart banner has been emitted
307	// for a session. First-writer-wins semantics, separate from StoreAgentTypeHint
308	// so a non-banner-capable agent winning the ownership race (e.g. Cursor, which
309	// doesn't implement HookResponseWriter) doesn't suppress the banner from a
310	// banner-capable agent that fires SessionStart for the same session.
311	//
312	// Callers MUST only invoke this from within the HookResponseWriter branch — the
313	// claim represents "a banner was actually shown", not just "an agent considered
314	// showing one". Otherwise a non-writer claimant would re-introduce the bug.
315	//
316	// Returns (claimed=true) when this call won the race and the caller should
317	// emit the banner; (claimed=false) when an earlier call already claimed it.
318	func ClaimSessionStartBanner(ctx context.Context, sessionID string) (claimed bool, err error) {
319		if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
320			return false, fmt.Errorf("invalid session ID: %w", vErr)
321		}
322	
323		stateDir, sErr := getSessionStateDir(ctx)
324		if sErr != nil {
325			return false, fmt.Errorf("failed to get session state directory: %w", sErr)
326		}
327		if mErr := os.MkdirAll(stateDir, 0o750); mErr != nil {
328			return false, fmt.Errorf("failed to create session state directory: %w", mErr)
329		}
330	
331		markerFile := filepath.Join(stateDir, sessionID+".banner")
332		f, oErr := os.OpenFile(markerFile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) //nolint:gosec // markerFile path is built from validated sessionID
333		if oErr != nil {
334			if errors.Is(oErr, os.ErrExist) {
335				return false, nil
336			}
337			return false, fmt.Errorf("failed to create banner marker file: %w", oErr)
338		}
339		_ = f.Close()
340		return true, nil
341	}
